144: 		public static double GetMinimumDistanceBetweenPointAndSegment(Point2D segmentPoint1, Point2D segmentPoint2, Point2D point)
145: 		{
146: 			Point2D A = segmentPoint1;
147: 			Point2D B = segmentPoint2;
148: 			Point2D C = point;
149: 
150: 			double BC = GetPointsDistance(B, C);
151: 			double AC = GetPointsDistance(A, C);
152: 			double AB = GetPointsDistance(A, B);
153: 
154: 			double squaredBC = Math.Pow(BC, 2);
155: 			double squaredAC = Math.Pow(AC, 2);
156: 			double squaredAB = Math.Pow(AB, 2);
157: 
158: 			if (squaredBC > squaredAC + squaredAB)
159: 			{
160: 				// 钝角三角形，∠A是钝角。
161: 				return AC;
162: 			}
163: 			else if (squaredAC > squaredBC + squaredAB)
164: 			{
165: 				// 钝角三角形，∠B是钝角。
166: 				return BC;
167: 			}
168: 			else
169: 			{
170: 				// A、B和C组成一个锐角三角形或直角三角形，或者A、B和C在同一直线上。
171: 
172: 				// “海伦公式”：由三角形的3条边长计算三角形的面积。
173: 				// 此公式同样支持A、B和C共线的情况。
174: 				double p = (BC + AC + AB) / 2;
175: 				double triangleArea = Math.Sqrt(p * (p - BC) * (p - AC) * (p - AB));
176: 				double triangleHeight = 2 * triangleArea / AB;
177: 
178: 				return triangleHeight;
179: 			}
180: 		}

189:         public static Point2D CalculatePointProjectionOnLine(Point2D linePointA, Point2D linePointB, Point2D point)
190:         {
191: 			if (linePointA == linePointB)
192: 				throw new ArgumentException(nameof(linePointB));
193: 
194:             // 直线方程：Ax + By + C = 0
195:             // 点: (x0, y0)
196:             // 法线方程：Bx - Ay + (-Bx0 + Ay0) = 0
197:             // 投影点：( (B * (-B * x0 + A * y0) + A * C) / (-A^2 - B^2), (B * C - A * (-B * x0 + A * y0)) / (-A^2 - B^2) )
198: 
199:             // 经过点A(xA, yB)和点B(xB, yB)的直线的一般方程：
200:             //   (yB - yA)x + (xA - xB)y + (xB*yA - xA*yB) = 0
201:             //  A = yB - yA
202:             //  B = xA - xB
203:             //  C = xB * yA - xA * yB
204:             //  
205:             // 投影点：
206:             //  x' = (x0 * B^2 - y0 * A * B - A * C) / (A^2 + B^2)
207:             //  y' = (y0 * A^2 - x0 * A * B - B * C) / (A^2 + B^2)
208: 
209:             Point2D a = linePointA;
210:             Point2D b = linePointB;
211:             Point2D c = point;
212: 
213:             double A = b.Y - a.Y;
214:             double B = a.X - b.X;
215:             double C = b.X * a.Y - a.X * b.Y;
216: 
217:             double AB = A * B;
218:             double AA = A * A;
219:             double BB = B * B;
220:             double AA_BB = AA + BB;
221: 
222:             double xProj = (c.X * BB - c.Y * AB - A * C) / AA_BB;
223:             double yProj = (c.Y * AA - c.X * AB - B * C) / AA_BB;
224: 
225:             return new Point2D((float)xProj, (float)yProj);
226:         }

234:         public static double CalculateVectorInclication(Point2D initialPoint, Point2D terminalPoint)
235:         {
236:             //float I_i = 1;
237:             //float I_j = 0;
238: 
239:             float V_i = terminalPoint.X - initialPoint.X;
240:             float V_j = terminalPoint.Y - initialPoint.Y;
241: 			double dotProduct = V_i;	// dotProduct = V_i * I_i + V_j * I_j  ==>  dotProduct = V_i
242: 
243:             double V_magnitude = Math.Sqrt(V_i * V_i + V_j * V_j);
244: 			//double I_magnitude = 1;
245: 
246:             double cos = dotProduct / V_magnitude;	// cos = dotProduct / V_magnitude / I_magnitude;  ==> cos = dotProduct / V_magnitude
247:             double radius = Math.Acos(cos);
248:             double degree = radius * 180 / Math.PI;
249: 
250:             return degree;            
251:         }

