67:         public override void HandleMouseMoveEvent(MouseEventArgs args)
68:         {
69:             Point2D mousePixelPoint = (Point2D)args.Location;
70:             Point2D mouseLogicalPoint = EpoxyPatternControl.ConvertToLogicalPoint(mousePixelPoint);
71: 
72:             if (_bHolding)
73:             {                
74:                 Curve curve = EpoxyPatternControl.GetCurrentCurve();
75:                 if (curve != null && curve.EndpointCount > 0)
76:                 {
77:                     float xIncrement = mouseLogicalPoint.X - _previousMouseLogicalPoint.X;
78:                     float yIncrement = mouseLogicalPoint.Y - _previousMouseLogicalPoint.Y;
79: 
80:                     if (Control.ModifierKeys == Keys.Shift)
81:                     {
82:                         yIncrement = 0;
83:                     }
84:                     else if (Control.ModifierKeys == Keys.Control)
85:                     {
86:                         xIncrement = 0;
87:                     }
88:                     else
89:                     { }
90: 
91:                     EpoxyPatternControl.TranslateCurrentCurve(xIncrement, yIncrement);
92: 
93:                     Point2D newMinLogicalPoint = new Point2D(MinLogicalPoint.X + xIncrement, MinLogicalPoint.Y + yIncrement);
94:                     Point2D newMaxLogicalPoint = new Point2D(MaxLogicalPoint.X + xIncrement, MaxLogicalPoint.Y + yIncrement);
95:                     SetMinAndMaxLogicalPoints(newMinLogicalPoint, newMaxLogicalPoint);
96: 
97:                     _previousMouseLogicalPoint = mouseLogicalPoint;
98: 
99:                     EpoxyPatternControl.Invalidate();
100:                 }
101:             }
102:             else
103:             {
104:                 if (MinLogicalPoint.X <= mouseLogicalPoint.X &&
105:                     MinLogicalPoint.Y <= mouseLogicalPoint.Y &&
106:                     mouseLogicalPoint.X <= MaxLogicalPoint.X &&
107:                     mouseLogicalPoint.Y <= MaxLogicalPoint.Y
108:                     )
109:                 {
110:                     EpoxyPatternControl.Cursor = Cursors.Hand;
111:                 }
112:                 else
113:                 {
114:                     EpoxyPatternControl.Cursor = Cursors.Default;
115:                 }
116:             }
117:         }

