134:         public override void HandleMouseMoveEvent(MouseEventArgs args)
135:         {
136:             Point2D mousePixelPoint = (Point2D)args.Location;
137:             Point2D mouseLogicalPoint = EpoxyPatternControl.ConvertToLogicalPoint(mousePixelPoint);
138: 
139:             if (_bHolding)
140:             {
141:                 Debug.Assert(_relation != PointAndRectangleRelation.Unkown);
142: 
143:                 Curve curve = EpoxyPatternControl.GetCurrentCurve();
144:                 if (curve != null && curve.EndpointCount > 0)
145:                 {
146:                     float xScale = 1;
147:                     float yScale = 1;
148: 
149:                     if ((_relation & PointAndRectangleRelation.VerticalEdges) != 0)
150:                     {
151:                         xScale = Math.Abs(mouseLogicalPoint.X / _previousMouseLogicalPoint.X);
152:                     }
153:                     else
154:                     {
155:                         if ((_relation & PointAndRectangleRelation.HorizontalEdges) != 0)
156:                         {
157:                             yScale = Math.Abs(mouseLogicalPoint.Y / _previousMouseLogicalPoint.Y);
158:                         }
159:                     }
160: 
161: 
162:                     if (Control.ModifierKeys == Keys.Shift)
163:                     {
164:                         if (xScale == 1 && yScale != 1)
165:                         {
166:                             xScale = yScale;
167:                         }
168:                         else if (xScale != 1 && yScale == 1)
169:                         {
170:                             yScale = xScale;
171:                         }
172:                         else
173:                         { }
174:                     }
175: 
176: 
177:                     _previousMouseLogicalPoint = mouseLogicalPoint;
178: 
179:                     bool bScalable = true;
180:                     if (!_bMinifiable)
181:                     {
182:                         if (xScale < 1 || yScale < 1)
183:                             bScalable = false;
184:                     }
185: 
186:                     if (bScalable)
187:                     {
188:                         try
189:                         {
190:                             int iPointIndex = 0;
191:                             foreach (Point2D point in _polygonLogicalPoints)
192:                             {
193:                                 _additionalLogicalPoints[iPointIndex] = point;
194:                                 iPointIndex++;
195:                             }
196: 
197:                             EpoxyPatternControl.ScaleCurrentCurve(_curveCenterLogicalPoint, xScale, yScale, ref _additionalLogicalPoints);
198: 
199:                             iPointIndex = 0;
200:                             for (int i = 0; i < _polygonLogicalPoints.Length; i++, iPointIndex++)
201:                             {
202:                                 _polygonLogicalPoints[i] = _additionalLogicalPoints[iPointIndex];
203:                                 _polygonPixelPoints[i] = (PointF)EpoxyPatternControl.CreateRealPoint(_polygonLogicalPoints[i]);
204:                             }
205: 
206:                             float polygonWidth = Math.Abs(_polygonLogicalPoints[0].X - _polygonLogicalPoints[1].X);
207:                             float polygonHeight = Math.Abs(_polygonLogicalPoints[0].Y - _polygonLogicalPoints[2].Y);
208:                             if (polygonWidth <= EpoxyPatternControl.EndpointRectWidth * 2 || polygonHeight <= EpoxyPatternControl.EndpointRectHeight * 2)
209:                             {
210:                                 _bMinifiable = false;
211:                             }
212:                             else
213:                             {
214:                                 _bMinifiable = true;
215:                             }
216:                         }
217:                         catch (InvalidOperationException)
218:                         {
219:                             _bHolding = false;
220:                         }
221: 
222:                         EpoxyPatternControl.Invalidate();
223:                     }
224:                 }
225:             }
226:             else
227:             {
228:                 var relation = Utility.CheckPointOnRectangleEdge(_outerRectangleMinPoint, _outerRectangleMaxPoint, mouseLogicalPoint, _xDelta, _yDelta);
229: 
230:                 switch (relation)
231:                 {
232:                 case PointAndRectangleRelation.LeftEdge:
233:                 case PointAndRectangleRelation.RightEdge:
234:                     EpoxyPatternControl.Cursor = Cursors.SizeWE;
235:                     break;
236: 
237:                 case PointAndRectangleRelation.TopEdge:
238:                 case PointAndRectangleRelation.BottomEdge:
239:                     EpoxyPatternControl.Cursor = Cursors.SizeNS;
240:                     break;
241: 
242:                 //case PointAndRectangleRelation.TopLeftCorner:
243:                 //case PointAndRectangleRelation.BottomRightCorner:
244:                 //    EpoxyPatternControl.Cursor = Cursors.SizeNESW;
245:                 //    break;
246: 
247:                 //case PointAndRectangleRelation.TopRightCorner:
248:                 //case PointAndRectangleRelation.BottomLeftCorner:
249:                 //    EpoxyPatternControl.Cursor = Cursors.SizeNWSE;
250:                 //    break;
251: 
252:                 case PointAndRectangleRelation.Unkown:
253:                 default:
254:                     EpoxyPatternControl.Cursor = Cursors.Default;
255:                     break;
256:                 }
257:             }
258:         }

