256:         public void Rotate(Point2D rotationCenter, float degree, ref Point2D[] additionalPoints)
257:         {
258:             Matrix matrix = new Matrix();
259:             matrix.RotateAt(degree, (PointF)rotationCenter);
260: 
261:             PointF[] points = new PointF[this.endpointUnitList.Count + additionalPoints.Length];
262:             int i = 0;
263:             foreach (EndpointUnit endpointUnit in this.endpointUnitList)
264:             {
265:                 points[i] = (PointF)endpointUnit.Endpoint.LogicalPoint;
266:                 i++;
267:             }
268: 
269:             foreach (Point2D point in additionalPoints)
270:             {
271:                 points[i] = (PointF)point;
272:                 i++;
273:             }
274: 
275:             matrix.TransformPoints(points);
276: 
277:             i = 0;
278:             foreach (EndpointUnit endpointUnit in this.endpointUnitList)
279:             {
280:                 endpointUnit.Endpoint = new Endpoint((Point2D)points[i]);
281:                 i++;
282:             }
283: 
284:             for (int j = 0; j < additionalPoints.Length; j++)
285:             {
286:                 additionalPoints[j] = (Point2D)points[i];
287:                 i++;
288:             }
289:         }

299:         public void Scale(Point2D fixedPoint, float xScale, float yScale, ref Point2D[] additionalPoints)
300:         {
301:             PointF[] points = new PointF[this.endpointUnitList.Count + additionalPoints.Length];
302: 
303:             int i = 0;
304:             foreach (EndpointUnit endpointUnit in this.endpointUnitList)
305:             {
306:                 points[i] = (PointF)endpointUnit.Endpoint.LogicalPoint;
307:                 i++;
308:             }
309: 
310:             foreach (Point2D point in additionalPoints)
311:             {
312:                 points[i] = (PointF)point;
313:                 i++;
314:             }
315: 
316:             Matrix matrix = new Matrix();
317:             matrix.Translate(-1 * fixedPoint.X, -1 * fixedPoint.Y, MatrixOrder.Append);
318:             matrix.Scale(xScale, yScale, MatrixOrder.Append);
319:             matrix.Translate(fixedPoint.X, fixedPoint.Y, MatrixOrder.Append);
320:             matrix.TransformPoints(points);
321: 
322:             foreach (Point2D point in points)
323:             {
324:                 if (float.IsNaN(point.X) || float.IsNaN(point.Y))
325:                     throw new InvalidOperationException("");
326:             }
327: 
328:             i = 0;
329:             foreach (EndpointUnit endpointUnit in this.endpointUnitList)
330:             {
331:                 endpointUnit.Endpoint = new Endpoint((Point2D)points[i]);
332:                 i++;
333:             }
334: 
335:             for (int j = 0; j < additionalPoints.Length; j++)
336:             {
337:                 additionalPoints[j] = (Point2D)points[i];
338:                 i++;
339:             }
340: 
341: 
342:         }

