519:             if (iCurveIndex < 0 || this.CurveList.Count <= iCurveIndex)
520:                 throw new ArgumentOutOfRangeException(nameof(iCurveIndex));
521: 
522:             return this.CurveList[iCurveIndex];
523:         }

548:         internal void RemoveCurve(int iCurveIndex)
549:         {
550:             if (iCurveIndex < 0 || iCurveIndex >= this.CurveList.Count)
551:                 throw new IndexOutOfRangeException(nameof(iCurveIndex));
552: 
553:             var eventArgs = new CurveDeletedEventArgs(iCurveIndex, this.CurveList[iCurveIndex]);
554: 
555:             this.CurveList.RemoveAt(iCurveIndex);
556:             OnCurveDeleted(eventArgs);
557: 
558:             if (iCurveIndex == this.iCurrentCurveIndex)
559:             {
560:                 int iOldCurrentIndex = this.iCurrentCurveIndex;
561:                 if (this.CurveList.Count == 0)
562:                 {
563:                     this.iCurrentCurveIndex = INVALID_CURVE_INDEX;
564:                 }
565:                 else
566:                 {
567:                     int iMaxIndex = this.CurveList.Count - 1;
568:                     this.iCurrentCurveIndex = Math.Max(0, Math.Min(this.iCurrentCurveIndex - 1, iMaxIndex));
569:                 }
570: 
571:                 OnCurrentCurveIndexChanged(new CurrentCurveIndexChangedEventArgs(iOldCurrentIndex, this.iCurrentCurveIndex));
572:                 Invalidate();
573:             }
574:         }

579:         internal void RemoveAllCurves()
580:         {
581:             if (this.CurveList.Count > 0)
582:             {
583:                 var eventArgs = new CurrentCurveIndexChangedEventArgs(this.iCurrentCurveIndex, INVALID_CURVE_INDEX);
584: 
585:                 this.iCurrentCurveIndex = INVALID_CURVE_INDEX;
586: 
587:                 OnCurrentCurveIndexChanged(eventArgs);
588: 
589:                 Curve[] curveArray = this.CurveList.ToArray();
590:                 this.CurveList.Clear();
591: 
592:                 int iCurveIndex = 0;
593:                 foreach (Curve curve in curveArray)
594:                 {
595:                     OnCurveDeleted(new CurveDeletedEventArgs(iCurveIndex, curve));
596:                     iCurveIndex++;
597:                 }
598: 
599:                 Invalidate();
600:             }
601:         }

