17: 		{
18: 			graphics.DrawLine(pen, (PointF)initialPoint, (PointF)terminalPoint);
19:             FillArrow(graphics, initialPoint, terminalPoint, brush);
20: 		}

22: 		public static void FillArrow(Graphics graphics, Point2D initialPoint, Point2D terminalPoint, Brush brush)
23: 		{
24: 			Point2D ptM, ptN, ptA;
25: 			if (initialPoint != terminalPoint)
26: 			{
27:                 CalculateArrowPoints(initialPoint, terminalPoint, out ptM, out ptN, out ptA);
28: 
29: 				PointF[] points = new PointF[] { (PointF)terminalPoint, (PointF)ptM, (PointF)ptN, (PointF)terminalPoint };
30: 				graphics.FillPolygon(brush, points);
31: 			}
32: 		}

34: 		public static void DrawVector(Graphics graphics, Point2D initialPoint, Point2D terminalPoint, Pen pen)
35: 		{
36: 			graphics.DrawLine(pen, (PointF)initialPoint, (PointF)terminalPoint);
37:             DrawArrow(graphics, initialPoint, terminalPoint, pen);
38: 		}

40: 		public static void DrawArrow(Graphics g, Point2D srcPoint, Point2D dstPoint, Pen pen)
41: 		{			
42: 			if (srcPoint != dstPoint)
43: 			{
44: 				Point2D ptM, ptN, ptA;
45:                 CalculateArrowPoints(srcPoint, dstPoint, out ptM, out ptN, out ptA);
46: 				g.DrawLines(pen, new PointF[] { (PointF)ptM, (PointF)dstPoint, (PointF)ptN});
47: 			}
48: 		}

50: 		static void CalculateArrowPoints(Point2D srcPt, Point2D dstPt, out Point2D ptM, out Point2D ptN, out Point2D ptA)
51: 		{
52: 			if (srcPt == dstPt)
53: 				throw new ArgumentException("srcPt == dstpt");
54: 
55: 			double tan = (double)(dstPt.Y - srcPt.Y) / (double)(dstPt.X - srcPt.X);
56: 			double sita = Math.Atan(tan);
57: 
58: 			double sin = Math.Sin(sita);
59: 			double cos = Math.Cos(sita);
60: 
61: 			ptA = new Point2D();
62: 			int L = 10;//箭头的长度
63: 			int H = 10;//箭头的宽度
64: 			if (dstPt.X >= srcPt.X)
65: 			{
66: 				ptA.X = (int)(dstPt.X - L * cos + 0.5);
67: 				ptA.Y = (int)(dstPt.Y - L * sin + 0.5);
68: 			}
69: 			else
70: 			{
71: 				ptA.X = (int)(dstPt.X + L * cos + 0.5);
72: 				ptA.Y = (int)(dstPt.Y + L * sin + 0.5);
73: 			}
74: 
75: 
76: 			ptM = new Point2D();
77: 			ptM.X = (int)(ptA.X - H / 2 * sin + 0.5);
78: 			ptM.Y = (int)(ptA.Y + H / 2 * cos + 0.5);
79: 
80: 			ptN = new Point2D();
81: 			ptN.X = (int)(ptA.X + H / 2 * sin + 0.5);
82: 			ptN.Y = (int)(ptA.Y - H / 2 * cos + 0.5);
83: 		}

