475:                     Endpoint terminalPoint = this.endpointUnitList[iTerminalPointIndex].Endpoint;
476:                     EndpointSetting initialPointInfo = this.endpointUnitList[iInitialPointIndex].EndpointInfo;
477: 
478:                     Brush brush = highlightPaintTool.Brush;
