1061:         {
1062:             using (Graphics graphics = Graphics.FromImage(this.backgroundBitmap))
1063:             {
1064:                 graphics.Clear(Color.White);
1065: 
1066:                 Point2D bitmapCenter = new Point2D(this.backgroundBitmap.Width / 2F, this.backgroundBitmap.Height / 2F);
1067: 
1068:                 InitBackgroundBitmap_BackgroundImage(graphics, bitmapCenter);
1069: 
1070:                 InitBackgroundBitmap_Grids(graphics, bitmapCenter);
1071:                 InitBackgroundBitmap_CoordinateAxies(graphics, bitmapCenter);
