1079:         private void InitBackgroundBitmap_BackgroundImage(Graphics graphics, Point2D bitmapCenter)
1080:         {
1081:             if (this.backgroundImageInfo.Image != null)
1082:             {
1083:                 SizeF imageSize = this.backgroundImageInfo.Image.Size;
1084: 
1085: 
1086:                 Matrix tmpMatrix = new Matrix();
1087:                 tmpMatrix.Scale(this.scale, this.scale, MatrixOrder.Append);
1088:                 float offsetX = bitmapCenter.X - imageSize.Width / 2F * this.scale;
1089:                 float offsetY = bitmapCenter.Y - imageSize.Height / 2F * this.scale;
1090:                 tmpMatrix.Translate(offsetX, offsetY, MatrixOrder.Append);               
1091: 
1092:                 tmpMatrix.Multiply(this.backgroundImageMatrix, MatrixOrder.Append);
1093: 
1094:                 GraphicsState state = graphics.Save();
1095:                 graphics.Transform = tmpMatrix;
1096:                 graphics.DrawImage(this.backgroundImageInfo.Image, 0, 0);
1097:                 graphics.Restore(state);
1098:             }
1099:         }

