589:         public bool ContainsEndpoint(Point2D logicalPoint, float xOffset, float yOffset, out Endpoint endpoint, out int iEndpointIndex)
590:         {
591:             endpoint = new Endpoint();
592: 
593:             RectangleF rect = new RectangleF(0, 0, xOffset * 2, yOffset * 2);
594: 
595:             bool bResult = false;
596:             iEndpointIndex = 0;
597: 
598:             foreach (EndpointUnit endpointUnit in this.endpointUnitList)
599:             {
600:                 Point2D point = endpointUnit.Endpoint.LogicalPoint;
601: 
602:                 rect.X = point.X - xOffset;
603:                 rect.Y = point.Y - yOffset;
604: 
605:                 if (rect.Contains((PointF)logicalPoint))
606:                 {
607:                     endpoint = endpointUnit.Endpoint;
608:                     bResult = true;
609:                     break;
610:                 }
611: 
612:                 iEndpointIndex++;
613:             }
614: 
615:             return bResult;
616:         }

625:         public bool ContainsSegment(Point2D realPoint, double distance, out int iSegmentInitialEndpointIndex)
626:         {            
627:             for (int i = 1; i < this.endpointUnitList.Count; i++)
628:             {
629:                 Point2D segmentInitialPoint = this.endpointUnitList[i - 1].Endpoint.RealPoint;
630:                 Point2D segmentTerminalPoint = this.endpointUnitList[i].Endpoint.RealPoint;
631:                 double minimumDistance = Utility.GetMinimumDistanceBetweenPointAndSegment(segmentInitialPoint, segmentTerminalPoint, realPoint);
632: 
633:                 if (minimumDistance <= distance)
634:                 {
635:                     iSegmentInitialEndpointIndex = i - 1;
636:                     return true;
637:                 }
638:             }
639: 
640:             iSegmentInitialEndpointIndex = EpoxyPatternControl.INVALID_ENDPOINT_INDEX;
641:             return false;
642:         }

