1610:         internal Point2D ConvertToLogicalPoint(Point2D pixelPoint)
1611:         {           
1612:             float x = (pixelPoint.X - this.coordinateSystemOrigin.X) / this.scale;
1613:             float y = (this.coordinateSystemOrigin.Y - pixelPoint.Y) / this.scale;
1614:             return new Point2D(x, y);
1615:         }

1646:         internal void CreateRealPointAndRealRectangle(Point2D logicalPoint, out Point2D realPoint, out RectangleF realRectangle)
1647:         {
1648:             float realPointX = this.coordinateSystemOrigin.X + logicalPoint.X * this.scale;
1649:             float realPointY = this.coordinateSystemOrigin.Y - logicalPoint.Y * this.scale;
1650:             realPoint = new Point2D(realPointX, realPointY);
1651: 
1652:             float rectX = realPointX - this.endpointRectSize.Width / 2;
1653:             float rectY = realPointY - this.endpointRectSize.Height / 2;
1654:             realRectangle = new RectangleF(new PointF(rectX, rectY), this.endpointRectSize);
1655:         }

1662:         internal Endpoint CreateEndpoint(Point2D logicalPoint)
1663:         {
1664:             Point2D realPoint;
1665:             RectangleF realRect;
1666:             CreateRealPointAndRealRectangle(logicalPoint, out realPoint, out realRect);
1667: 
1668:             return new Endpoint(logicalPoint, realPoint, realRect);
1669:         }

