41:         public override void HandleMouseDownEvent(MouseEventArgs args)
42:         {
43:             Point2D mousePixelPoint = (Point2D)args.Location;
44:             Point2D mouseLogicalPoint = EpoxyPatternControl.ConvertToLogicalPoint(mousePixelPoint);
45: 
46:             if (MinLogicalPoint.X <= mouseLogicalPoint.X &&
47:                 MinLogicalPoint.Y <= mouseLogicalPoint.Y &&
48:                 mouseLogicalPoint.X <= MaxLogicalPoint.X &&
49:                 mouseLogicalPoint.Y <= MaxLogicalPoint.Y
50:                 )
51:             {
52:                 EpoxyPatternControl.Cursor = Cursors.SizeAll;
53: 
54:                 _mouseDownLogicalPoint = mouseLogicalPoint;
55:                 _previousMouseLogicalPoint = mouseLogicalPoint;
56:                 _originalMinLogicalPoint = MinLogicalPoint;
57:                 _originalMaxLogicalPoint = MaxLogicalPoint;
58:                 _bHolding = true;
59:             }
60:             else
61:             {
62:                 EpoxyPatternControl.Cursor = Cursors.Default;
63:                 _bHolding = false;
64:             }
65:         }

67:         public override void HandleMouseMoveEvent(MouseEventArgs args)
68:         {
69:             Point2D mousePixelPoint = (Point2D)args.Location;
70:             Point2D mouseLogicalPoint = EpoxyPatternControl.ConvertToLogicalPoint(mousePixelPoint);
71: 
72:             if (_bHolding)
73:             {                
74:                 Curve curve = EpoxyPatternControl.GetCurrentCurve();
75:                 if (curve != null && curve.EndpointCount > 0)
76:                 {
77:                     float xIncrement = mouseLogicalPoint.X - _previousMouseLogicalPoint.X;
78:                     float yIncrement = mouseLogicalPoint.Y - _previousMouseLogicalPoint.Y;
79: 
80:                     if (Control.ModifierKeys == Keys.Shift)
81:                     {
82:                         yIncrement = 0;
83:                     }
