81:         public static void GetCurveBounds(Curve curve, out float xMin, out float yMin, out float xMax, out float yMax)
82:         {
83:             if (curve == null)
84:                 throw new ArgumentNullException(nameof(curve));
85:             
86:             if (curve.EndpointCount == 0)
87:                 throw new InvalidOperationException("the curve does not contain endpoints");
88: 
89:             xMin = float.MaxValue;
90:             xMax = float.MinValue;
91:             yMin = float.MaxValue;
92:             yMax = float.MinValue;
93:             foreach (EndpointUnit endpointUnit in curve.EndpointUnitList)
94:             {
95:                 Point2D logicalPoint = endpointUnit.Endpoint.LogicalPoint;
