97:                 if (xMin > logicalPoint.X)
98:                     xMin = logicalPoint.X;
99: 
100:                 if (xMax < logicalPoint.X)
101:                     xMax = logicalPoint.X;
102: 
103:                 if (yMin > logicalPoint.Y)
104:                     yMin = logicalPoint.Y;
105: 
106:                 if (yMax < logicalPoint.Y)
107:                     yMax = logicalPoint.Y;
108:             }
109: 
110:             Debug.Assert(xMin != float.NaN && xMax != float.NaN);
111:             Debug.Assert(yMin != float.NaN && yMax != float.NaN);
112:             Debug.Assert(xMin <= xMax && yMin <= yMax);
