291:         public List<EPEPointData[]> ChangeListPosToPatternData(EpoxyApplication epoxyApplication)
292:         {
293:             List<EPEPointData[]> list = new List<EPEPointData[]>();
294: 
295:             if (epoxyApplication.DispensePatternParas != null && epoxyApplication.DispensePatternParas.Count > 0)
296:             {
297:                 foreach (EpoxyApplicationLocation[] epoxyApplicationLocations in epoxyApplication.DispensePatternParas)
298:                 {
299:                     EPEPointData[] epePointDatas = new EPEPointData[epoxyApplicationLocations.Length];
300: 
301:                     for (int j = 0; j < epoxyApplicationLocations.Length; j++)
302:                     {
303:                         EndpointSetting endpointInfo = new EndpointSetting
304:                         {
305:                             Acc = epoxyApplicationLocations[j].Acc,
306:                             AltitudeCompensation = (int)epoxyApplicationLocations[j].AltitudeCompensation,
307:                             Dummied = !epoxyApplicationLocations[j].OpenGlueFlag,
308:                             MaxSpeed = (int)epoxyApplicationLocations[j].Speed,
309:                             EndSpeed = (int)epoxyApplicationLocations[j].EndSpeed,
310:                             Time = epoxyApplicationLocations[j].DripTime,
311:                             PreDelay = epoxyApplicationLocations[j].AdvanceClose,
312:                             PostDelay = epoxyApplicationLocations[j].LagOpen,
313:                             HeightMeasurement = false
314:                         };
315: 
316:                         EPEPointData epePoint = new EPEPointData(
317:                             (float)epoxyApplicationLocations[j].X * 1000,
318:                             (float)epoxyApplicationLocations[j].Y * 1000,
319:                             endpointInfo);
320:                         epePointDatas[j] = epePoint;
321:                     }
322: 
323:                     list.Add(epePointDatas);
324:                 }
325:             }
326: 
327:             return list;
328:         }

334:         public void InitPatternData(EPEData epeData)
335:         {
336:             // 清空数据
337:             this.EpoxyApplication.DispensePatternParas.Clear();
338: 
339:             List<EPEPointData[]> list = epeData.EpePointList;
340: 
341:             for (int i = 0; i < list.Count; i++)
342:             {
343:                 EpoxyApplicationLocation[] dispenseLocations = new EpoxyApplicationLocation[epeData.EpePointList[i].Length];
344:                 for (int j = 0; j < epeData.EpePointList[i].Length; j++)
345:                 {
346:                     EpoxyApplicationLocation dispenseLocation = new EpoxyApplicationLocation
347:                         {
348:                             X = epeData.EpePointList[i][j].X / 1000,
349:                             Y = epeData.EpePointList[i][j].Y / 1000,
350:                             Acc = epeData.EpePointList[i][j].Info.Acc,
351:                             Speed = epeData.EpePointList[i][j].Info.MaxSpeed,
352:                             AltitudeCompensation = epeData.EpePointList[i][j].Info.AltitudeCompensation,
353:                             Dec = epeData.EpePointList[i][j].Info.Acc,
354:                             DripTime = epeData.EpePointList[i][j].Info.Time,
355:                             AdvanceClose = epeData.EpePointList[i][j].Info.PreDelay,
356:                             LagOpen = epeData.EpePointList[i][j].Info.PostDelay,
357:                             OpenGlueFlag = !epeData.EpePointList[i][j].Info.Dummied
358:                         };
359: 
360:                     dispenseLocations[j] = dispenseLocation;
361:                 }
362: 
363:                 this.EpoxyApplication.DispensePatternParas.Add(dispenseLocations);
364:             }
365: 
366:             DispenserMoveHelper.EpoxyPretreatment(this.EpoxyApplication, new AKRSPoint3D(), 0);
367: 
368:             this.Refresh();
369:         }

